// Package repository provides the data access layer for OCIDex.
// Most code in this package is generated by sqlc. This file defines
// the repository interface used by the service layer.
package repository

import (
	"context"

	"github.com/jackc/pgx/v5/pgtype"
)

// SBOMRepository defines the data access methods for SBOM persistence.
type SBOMRepository interface {
	InsertSBOM(ctx context.Context, arg InsertSBOMParams) (InsertSBOMRow, error)
	InsertComponent(ctx context.Context, arg InsertComponentParams) (pgtype.UUID, error)
	InsertComponentHash(ctx context.Context, arg InsertComponentHashParams) error
	UpsertLicenseBySPDX(ctx context.Context, arg UpsertLicenseBySPDXParams) (pgtype.UUID, error)
	UpsertLicenseByName(ctx context.Context, arg UpsertLicenseByNameParams) (pgtype.UUID, error)
	InsertComponentLicense(ctx context.Context, arg InsertComponentLicenseParams) error
	InsertDependency(ctx context.Context, arg InsertDependencyParams) error
	InsertExternalReference(ctx context.Context, arg InsertExternalReferenceParams) error
	DeleteSBOM(ctx context.Context, id pgtype.UUID) (int64, error)
	UpsertArtifactNamespace(ctx context.Context, arg UpsertArtifactNamespaceParams) error
}

